import{_ as a,o as e,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — View Material Repository","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-11-view-material-repository/spec.md","filePath":"feature/content-task-workflow/3-6-11-view-material-repository/spec.md"}'),r={name:"feature/content-task-workflow/3-6-11-view-material-repository/spec.md"};function n(c,t,l,h,s,d){return e(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="uc-—-view-material-repository" tabindex="-1">UC — View Material Repository <a class="header-anchor" href="#uc-—-view-material-repository" aria-label="Permalink to &quot;UC — View Material Repository&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.11</td></tr><tr><td>Feature</td><td>View Material Repository</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR, CLIENT</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Kho ảnh/video của người chụp/editor, phân loại raw vs đã retouched, cảnh báo dùng ảnh raw; kèm Brand Asset do Client cung cấp để Creator tham khảo.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator hoặc Client, tôi muốn xem kho tài liệu ảnh/video của Workspace, để tìm material phù hợp khi tạo content.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>List Material theo Workspace, phân loại <code>raw</code> | <code>retouched</code>.</li><li>Ảnh <code>raw</code> hiển thị badge cảnh báo — nhắc Creator không dùng trực tiếp lên bài đăng chính thức mà chưa xử lý.</li><li><strong>Brand Collection</strong> riêng biệt: tài liệu do CLIENT cung cấp để Creator tham khảo khi sáng tạo — khác Material Repository (Material là sản phẩm do Creator/photographer tạo, Brand Collection là input từ Client).</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Trang <code>/workspaces/:id/materials</code>, tab riêng cho Material Repository và Brand Collection.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/workspaces/{id}/materials?type=raw|retouched</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: [{ &quot;id&quot;, &quot;url&quot;, &quot;type&quot;, &quot;uploadedBy&quot;, &quot;uploadedAt&quot; }] }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/workspaces/{id}/brand-collection</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: [{ &quot;id&quot;, &quot;url&quot;, &quot;uploadedByClientId&quot;, &quot;note&quot; }] }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Không có quyền truy cập Workspace → 403 <code>FORBIDDEN</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>File raw chưa qua retouch bị dùng trực tiếp trong 1 Task đã submit → cảnh báo hiển thị ở Task Detail, không chặn cứng submit (Manager tự quyết định reject nếu không đồng ý).</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Hiển thị đúng phân loại, cảnh báo raw hoạt động.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/05-content-task-workflow.html">05-content-task-workflow.md</a></p>`,22)])])}const k=a(r,[["render",n]]);export{p as __pageData,k as default};
